// We import the Verus prelude so that `#[requires]`, `#[ensures]` etc.
// are in scope.  Nothing else in your code need change.
use verus::prelude::*;

fn main() {
    let mut v1 = vec![1, 5, 3, 7, 2];
    replace(&mut v1, 4);
    assert_eq!(v1, vec![1, -1, 3, -1, 2]);

    let mut v2: Vec<i32> = Vec::new();
    replace(&mut v2, 10);
    assert!(v2.is_empty());

    let mut v3 = vec![-5, 0, 5, 10];
    replace(&mut v3, 0);
    assert_eq!(v3, vec![-5, 0, -1, -1]);

    println!("All tests passed.");
}

// We add a pre/post‐condition on `replace`.
//   • requires(true) just says “no preconditions”
//   • ensures(...) says that in the post‐state the mutated `arr`
//     has the same length as it did before, and that each element
//     has been set to −1 exactly when the old value was > k,
//     otherwise it remains equal to its old value.
#[requires(true)]
#[ensures(
    // The closure parameters are: the old Vec, the new Vec, and k
    |old_arr: &Vec<i32>, new_arr: &Vec<i32>, k0: i32| {
        // length is unchanged
        new_arr.len() == old_arr.len()
        // for every index in‐bounds, we have the intended replacement law
        && forall(|i: usize| i < old_arr.len() ==>
            if old_arr[i] > k0 {
                new_arr[i] == -1
            } else {
                new_arr[i] == old_arr[i]
            }
        )
    }
)]
fn replace(arr: &mut Vec<i32>, k: i32) {
    for elem in arr.iter_mut() {
        if *elem > k {
            *elem = -1;
        }
    }
}